    def is_returnable(n, s):
        visited = [False] * n
        direction = [None] * n

        def dfs(room, prev_dir):
            if visited[room]:
                return direction[room] == prev_dir
            visited[room] = True
            direction[room] = prev_dir

            if s[room] == '>':
                return dfs((room + 1) % n, '>')
            elif s[room] == '<':
                return dfs((room - 1) % n, '<')
            else:
                return dfs((room + 1) % n, '>') or dfs((room - 1) % n, '<')

        returnable_count = 0
        for i in range(n):
            if not visited[i]:
                if dfs(i, None):
                    returnable_count += 1
        return returnable_count

